const row = $input.first().json;
const clp = (n) => '$' + String(n ?? 0).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const lines = [
  'Entraron: ' + row.entries,
  'Contactados: ' + row.contacted,
  'Cotizados: ' + row.quoted,
  'Ganados: ' + row.won + ' (' + clp(row.won_amount) + ')',
  'Perdidos: ' + row.lost,
  'Sin atender: ' + row.unattended,
  'Seguimientos vencidos: ' + row.overdue_followups,
];
return [{ json: { text: lines.join('\n') } }];
